Python<pre><code># 定义罚函数
def g(X):
    return max(0, h(X)) ** 2


# 定义罚函数的梯度
def grad_g(X):
    if h(X) &gt; 0:
        return np.array([2 * h(X) * 2 * X[0], 2 * h(X) * 2 * X[1]])
    else:
        return np.array([0, 0])


# 定义加入罚函数之后的目标函数
def penalty(X, u):
    return f(X) + u * g(X)


# 定义加入罚函数之后的目标函数的梯度
def grad_penalty(X, u):
    return grad_f(X) + u * grad_g(X)
